// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address actor, uint96 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        uint256 amt = bound(uint256(amount), 1, type(uint96).max);

        vm.deal(actor, amt);
        vm.prank(actor);
        c.deposit{value: amt}();

        vm.prank(actor);
        c.withdrawAll();

        assertTrue(address(c).balance == 0);
    }
}
